import org.junit.Test;
import org.junit.Assert;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.TextNode;

public class TextNodeTest {

    @Test
    public void textNodeConstructorTest() {
        String testText = "Test Text";
        TextNode textNode = new TextNode(testText);
        Assert.assertEquals(testText, textNode.text());
    }

    @Test
    public void nodeNameTest() {
        TextNode textNode = new TextNode("Test Text");
        Assert.assertEquals("#text", textNode.nodeName());
    }

    @Test
    public void setTextTest() {
        TextNode textNode = new TextNode("Initial Text");
        String newText = "Updated Text";
        textNode.text(newText);
        Assert.assertEquals(newText, textNode.text());
    }

    @Test
    public void getWholeTextTest() {
        String text = "Whole Text Data";
        TextNode textNode = new TextNode(text);
        Assert.assertEquals(text, textNode.getWholeText());
    }

    @Test
    public void isBlankTest() {
        TextNode textNodeEmpty = new TextNode("");
        TextNode textNodeNotEmpty = new TextNode("NotEmpty");
        Assert.assertTrue(textNodeEmpty.isBlank());
        Assert.assertFalse(textNodeNotEmpty.isBlank());
    }

    @Test
    public void splitTextTest() {
        String text = "Text to Split";
        int splitPoint = 4;
        TextNode textNode = new TextNode(text);
        TextNode splitted = textNode.splitText(splitPoint);
        Assert.assertEquals(text.substring(0, splitPoint), textNode.text());
        Assert.assertEquals(text.substring(splitPoint), splitted.text());
    }

    @Test
    public void outerHtmlHeadTest() throws IOException {
        String text = "OuterHtmlHead Text";
        TextNode textNode = new TextNode(text);
        StringBuilder sb = new StringBuilder();
        Document.OutputSettings out = new Document.OutputSettings();
        textNode.outerHtmlHead(sb, 0, out);
        Assert.assertEquals(text, sb.toString());
    }

    @Test
    public void outerHtmlTailTest() {
        TextNode textNode = new TextNode("OuterHtmlTail Text");
        StringBuilder sb = new StringBuilder();
        Document.OutputSettings out = new Document.OutputSettings();
        textNode.outerHtmlTail(sb, 0, out);
        Assert.assertEquals("", sb.toString());
    }

    @Test
    public void toStringTest() {
        String text = "ToString Text";
        TextNode textNode = new TextNode(text);
        Assert.assertEquals(text, textNode.toString());
    }

    @Test
    public void cloneTest() {
        String text = "Clone Text";
        TextNode textNode = new TextNode(text);
        TextNode clone = textNode.clone();
        Assert.assertEquals(textNode.text(), clone.text());
        Assert.assertNotSame(textNode, clone);
    }

    @Test
    public void createFromEncodedTest() {
        String text = "Encoded Text";
        TextNode textNode = TextNode.createFromEncoded(text);
        Assert.assertEquals(text, textNode.text());
    }
}
